window.HOEREN_TESTS[38] = {"id":"am-flughafen","name":"Am Flughafen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Achtung, eine wichtige Durchsage: Der Flug LH 405 nach Berlin ist verspätet. Statt 14 Uhr 30 startet er nicht um 15 Uhr 30, sondern nun um 16 Uhr 15. Wir bitten alle Passagiere, beim Gate 27 zu warten. Tickets bleiben gültig, vielen Dank für Ihr Verständnis und Ihre Geduld heute am Gate. Danke!","gender":"f","q":"Wann startet der Flug jetzt?","opts":["16:15.","15:30.","14:30."],"correct":0},{"transcript":"Liebe Passagiere des Fluges nach Wien: Wir haben eine Gate-Änderung. Der Flug startet nicht von Gate 12 und nicht von Gate 2, sondern von Gate 22. Bitte gehen Sie jetzt zum neuen Gate und folgen Sie den Schildern. Boarding beginnt in 20 Minuten, wir wünschen einen guten Flug, vielen Dank.","gender":"m","q":"Welches Gate ist jetzt richtig?","opts":["Gate 12.","Gate 22.","Gate 2."],"correct":1},{"transcript":"Hi Lisa, hier ist Tom. Mein Flug ist gelandet, ich bin nicht krank, und der Flug fiel nicht aus. Aber mein Koffer ist weg, er ist am Frankfurter Flughafen geblieben. Sie schicken ihn morgen nach. Hol mich bitte ohne Gepäck ab. Ich bin am Ausgang in 30 Minuten. Danke!","gender":"m","q":"Was ist das Problem?","opts":["Der Koffer ist weg.","Tom ist krank.","Der Flug fiel aus."],"correct":0},{"transcript":"Letzte Durchsage für den Flug nach Paris: Wir schließen die Tür in 5 Minuten! Passagier Herr Müller, bitte sofort zum Gate 14. Nicht Herr Schmidt und nicht Frau Müller, nur Herr Müller. Wenn Sie nicht in 5 Minuten kommen, startet das Flugzeug ohne Sie. Wir wiederholen: Herr Müller zum Gate 14!","gender":"f","q":"Wer wird gerufen?","opts":["Herr Schmidt.","Herr Müller.","Frau Müller."],"correct":1},{"transcript":"Information für alle Reisenden: Heute ist die Sicherheitskontrolle besonders streng. Bitte rechnen Sie mit längeren Wartezeiten, etwa 45 Minuten, nicht nur 15 Minuten und nicht ganz eine Stunde. Wir empfehlen, früher zum Flughafen zu kommen. Wasser und Flüssigkeiten dürfen wie immer nicht im Handgepäck sein, bitte prüfen Sie das.","gender":"m","q":"Wie lange dauert die Kontrolle ungefähr?","opts":["Eine Stunde.","15 Minuten.","45 Minuten."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer fliegt wohin? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Anzeigetafel am Flughafen wechselt schon wieder."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Fast alle aus der Gruppe fliegen diese Woche weit weg."},{"speaker":"Lukas","gender":"m","text":"Mein Flug geht nach New York. Morgen früh bin ich in der Luft."},{"speaker":"Lisa","gender":"f","text":"Das ist ein weiter Weg. Du bleibst zwei Wochen dort."},{"speaker":"Lukas","gender":"m","text":"Fliegt noch jemand von euch nach Wien?"},{"speaker":"Lisa","gender":"f","text":"Nein. Nach Wien fliegt keiner."},{"speaker":"Lukas","gender":"m","text":"Dein Koffer steht schon fertig an der Tür."},{"speaker":"Lisa","gender":"f","text":"Ich lande in London. Am Sonntag wartet dort meine Cousine."},{"speaker":"Lukas","gender":"m","text":"Tom zeigt seit Tagen Fotos von einem hohen Turm."},{"speaker":"Lisa","gender":"f","text":"Tom fliegt nach Paris. Er will die Stadt zu Fuß sehen."},{"speaker":"Lukas","gender":"m","text":"Sara spricht nur noch von alten Plätzen und Sonne."},{"speaker":"Lisa","gender":"f","text":"Sara reist nach Rom. Drei Nächte bei einer Freundin reichen ihr."},{"speaker":"Lukas","gender":"m","text":"Ist Istanbul auch auf der Liste?"},{"speaker":"Lisa","gender":"f","text":"Nein. Istanbul ist es auch nicht."},{"speaker":"Lukas","gender":"m","text":"Tim hat ein langes Praktikum ganz im Osten."},{"speaker":"Lisa","gender":"f","text":"Tim startet nach Tokio. Er bleibt dort einen ganzen Monat."},{"speaker":"Lukas","gender":"m","text":"Dann bringen wir die Koffer heute Abend zum Schalter."},{"speaker":"Lisa","gender":"f","text":"Ich wünsche allen eine gute Reise."}],"options":[{"letter":"a","text":"Rom"},{"letter":"b","text":"Wien"},{"letter":"c","text":"New York"},{"letter":"d","text":"Tokio"},{"letter":"e","text":"Istanbul"},{"letter":"f","text":"Paris"},{"letter":"g","text":"Amsterdam"},{"letter":"h","text":"London"},{"letter":"i","text":"Madrid"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"h"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"a"},{"person":"Tim","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Passagier","gender":"m","text":"Wo ist der Check-in für Lufthansa? Kann ich zu Fuß gehen, oder besser Bus oder Shuttle?"},{"speaker":"Info-Dame","gender":"f","text":"Terminal 2, Schalter 30 bis 50, zu Fuß gehen ist zu weit mit Gepäck."},{"speaker":"Passagier","gender":"m","text":"Wie komme ich dahin? Bus, Shuttle, oder zu Fuß?"},{"speaker":"Info-Dame","gender":"f","text":"Bus oder Shuttle, der Bus ist langsamer, der Shuttle kommt alle 5 Minuten. Zu Fuß rate ich nicht."},{"speaker":"Passagier","gender":"m","text":"Dann nehme ich den Shuttle. Danke, das ist klar."}],"q":"Was empfiehlt sie?","opts":["Den Shuttle.","Zu Fuß gehen.","Den Bus."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Mein Koffer ist zu schwer. Was kostet Extra-Gewicht? Oder lasse ich den Koffer da?"},{"speaker":"Mann am Schalter","gender":"m","text":"Pro Kilo 15 Euro, 5 Kilo zu viel, das wären 75 Euro. Den Koffer da lassen geht nicht."},{"speaker":"Frau","gender":"f","text":"Kann ich Sachen ins Handgepäck nehmen? Dann zahle ich nicht 75 Euro."},{"speaker":"Mann am Schalter","gender":"m","text":"Ja, nehmen Sie Sachen ins Handgepäck. Dann sparen Sie das Geld."},{"speaker":"Frau","gender":"f","text":"Gut, dann packe ich um. 75 Euro zahle ich nicht, den Koffer lasse ich nicht da."}],"q":"Was macht die Frau?","opts":["Lässt den Koffer da.","Zahlt 75 Euro.","Nimmt Sachen ins Handgepäck."],"correct":2},{"lines":[{"speaker":"Pilot","gender":"m","text":"Liebe Passagiere, der Flug nach München dauert eine Stunde 20 Minuten, nicht eine Stunde und nicht zwei Stunden."},{"speaker":"Passagier","gender":"m","text":"Was? Ich dachte, eine Stunde, zwei Stunden wäre lang."},{"speaker":"Stewardess","gender":"f","text":"Wegen Wind etwas länger heute, ja. Eine Stunde 20, nicht zwei Stunden."},{"speaker":"Passagier","gender":"m","text":"Verstanden, hauptsache wir kommen an. Eine Stunde wäre schöner gewesen."},{"speaker":"Stewardess","gender":"f","text":"Wir starten gleich, bitte machen Sie den Gurt fest."}],"q":"Wie lange dauert der Flug?","opts":["Eine Stunde 20.","Eine Stunde.","Zwei Stunden."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, wann holt uns Oma ab? Mit dem Bus, mit dem Auto oder mit dem Zug?"},{"speaker":"Vater","gender":"m","text":"Sie wartet schon am Ankunftsbereich. Nicht mit dem Zug, der fährt woanders."},{"speaker":"Tochter","gender":"f","text":"Mit dem Auto? Das wäre schnell."},{"speaker":"Vater","gender":"m","text":"Nein, mit dem Bus, das Auto ist kaputt, und den Zug nimmt sie heute nicht."},{"speaker":"Tochter","gender":"f","text":"Okay, dann Bus, ich passe auf das Gepäck auf."}],"q":"Wie kommt Oma?","opts":["Mit dem Auto.","Mit dem Bus.","Mit dem Zug."],"correct":1},{"lines":[{"speaker":"Tourist","gender":"m","text":"Wo finde ich ein Taxi? Oder ist Zug oder Bus besser ins Zentrum?"},{"speaker":"Polizist","gender":"m","text":"Taxi vor dem Terminal, rechte Seite. Bus auch, aber der dauert länger."},{"speaker":"Tourist","gender":"m","text":"Ungefährer Preis ins Zentrum mit dem Taxi?"},{"speaker":"Polizist","gender":"m","text":"Etwa 35 Euro, mit dem Zug nur 5 Euro. Der Bus kostet 8 Euro und braucht eine Stunde."},{"speaker":"Tourist","gender":"m","text":"Dann lieber Zug, taxi ist zu teuer, und den Bus will ich nicht."}],"q":"Wie fährt der Tourist?","opts":["Taxi.","Bus.","Zug."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Lange, einem Piloten. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Kapitän Lange, Sie sind seit 25 Jahren Pilot. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Lange","gender":"m","text":"Als Kind wollte ich Astronaut werden — aber das war zu schwer. Pilot war der Plan B. Ich habe die Ausbildung mit 22 angefangen, mit 25 war ich Co-Pilot, mit 35 Kapitän. Heute fliege ich Langstrecke nach Asien und Amerika."},{"speaker":"Reporterin","gender":"f","text":"Ist Fliegen heute anders als früher?"},{"speaker":"Lange","gender":"m","text":"Sehr, die Flugzeuge sind moderner, sicherer, der Computer macht viel. Aber die Verantwortung ist gleich groß. Auch das Wetter ist unberechenbarer geworden — Klimawandel, glaube ich."},{"speaker":"Reporterin","gender":"f","text":"Hatten Sie schon gefährliche Situationen?"},{"speaker":"Lange","gender":"m","text":"Ein paar Mal, ja. Starker Sturm über dem Atlantik einmal — wir mussten umkehren. Vögel im Triebwerk einmal — Notlandung. Aber niemand wurde verletzt. Das Training hilft sehr."},{"speaker":"Reporterin","gender":"f","text":"Wie ist Ihr Privatleben?"},{"speaker":"Lange","gender":"m","text":"Schwierig manchmal. Ich bin oft weg, lange. Meine Frau ist auch Stewardess, sie versteht das. Aber Kinder haben wir keine — das wäre zu schwer mit unserem Job."},{"speaker":"Reporterin","gender":"f","text":"Was empfehlen Sie Passagieren?"},{"speaker":"Lange","gender":"m","text":"Keine Angst! Fliegen ist statistisch sicherer als Autofahren. Und: viel Wasser trinken im Flugzeug, sich bewegen — die Luft ist trocken."}],"items":[{"q":"Heute machen Computer alles allein im Cockpit.","correct":"nein"},{"q":"Herr Lange wollte als Kind Astronaut werden.","correct":"ja"},{"q":"Er hatte schon eine Notlandung wegen Vögeln.","correct":"ja"},{"q":"Er und seine Frau haben Kinder.","correct":"nein"},{"q":"Er empfiehlt Passagieren, viel Wasser zu trinken.","correct":"ja"}]}]};
